#include "stdlib/number/float16/ctor.h"
#include "stdlib/constants/float32/sign_mask.h"
#include "stdlib/constants/float32/exponent_mask.h"
#include "stdlib/constants/float32/significand_mask.h"
#include "stdlib/constants/float32/num_significand_bits.h"
#include "stdlib/constants/float16/sign_mask.h"
#include "stdlib/constants/float16/exponent_mask.h"
#include "stdlib/constants/float16/significand_mask.h"
#include "stdlib/constants/float16/num_significand_bits.h"
#include "stdlib/number/float32/base/exponent.h"
#include <stdint.h>
#include <string.h>

// VARIABLES //

static const uint32_t FLOAT32_MAX_EXPONENT = 255;
static const uint32_t FLOAT16_MAX_EXPONENT = 31;
static const uint16_t UINT16_PINF = 0x7C00;            // 0x7C00 = 31744 => 0 11111 0000000000
static const uint16_t UINT16_NINF = 0xFC00;            // 0xFC00 = 64512 => 1 11111 0000000000
static const uint16_t UINT16_NAN = 0x7E00;             // 0x7E00 = 32256 => 0 11111 1000000000
static const uint16_t UINT16_POSITIVE_ZERO = 0x0000;   // 0x0000 = 0 => 0 00000 0000000000
static const uint16_t UINT16_NEGATIVE_ZERO = 0x8000;   // 0x8000 = 32768 => 1 00000 0000000000
static const uint32_t FLOAT32_IMPLICIT_BIT = 0x800000; // 0x800000 = 8388608 => 0 00000001 00000000000000000000000
static const uint32_t FLOAT32_STICKY_MASK = 0xFFF;     // 0xFFF = 4095 => 0 00000000 00000000000111111111111
static const uint16_t MAX_MANTISSA = 0x3FF;            // 0x3FF = 1023 => 0 00000 1111111111

/**
* Converts a single-precision floating-point number to a half-precision floating-point number.
*
* @param value    single-precision floating-point number
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_float32( 5.0f );
*/
stdlib_float16_t stdlib_float16_from_float32( const float value ) {
	stdlib_float16_t result;
	uint32_t f32Mantissa;
	uint32_t f32Exponent;
	uint32_t f16Mantissa;
	uint32_t sticky_bits;
	int32_t f16Exponent;
	uint32_t round_bit;
	uint32_t sign;
	uint32_t f32;
	int shift;

	// Copy float bits to uint32_t
	memcpy( &f32, &value, sizeof(float) );

	// Extract sign bit and shift to bit 15:
	sign = ( f32 & STDLIB_CONSTANT_FLOAT32_SIGN_MASK ) >> 16;

	// Extract exponent bits:
	f32Exponent = ( f32 & STDLIB_CONSTANT_FLOAT32_EXPONENT_MASK ) >> STDLIB_CONSTANT_FLOAT32_NUM_SIGNIFICAND_BITS;

	// Extract mantissa bits:
	f32Mantissa = f32 & STDLIB_CONSTANT_FLOAT32_SIGNIFICAND_MASK;

	// Handle special cases...
	if ( f32Exponent == FLOAT32_MAX_EXPONENT ) {
		if ( f32Mantissa == 0 ) {
			if ( sign ) {
				result.bits = UINT16_NINF; // -Infinity
			} else {
				result.bits = UINT16_PINF; // +Infinity
			}
		} else {
			result.bits = UINT16_NAN; // NaN
		}
		return result;
	}

	if ( f32Exponent == 0 && f32Mantissa == 0 ) {
		if (sign) {
			result.bits = UINT16_NEGATIVE_ZERO;
		} else {
			result.bits = UINT16_POSITIVE_ZERO;
		}
		return result;
	}

	// Convert exponent from float32 bias (127) to float16 bias (15)
	f16Exponent = stdlib_base_float32_exponent( value ) + 15;

	// Handle overflow (infinity in float16)...
	if ( f16Exponent >= 31 ) {
		if ( sign ) {
			result.bits = UINT16_NINF; // -Infinity
		} else {
			result.bits = UINT16_PINF; // +Infinity
		}
		return result;
	}

	// Handle underflow (subnormal or zero in float16)...
	if ( f16Exponent <= 0 ) {
		// Check if the value is too small to be represented even as a subnormal float16 number:
		if ( f16Exponent < -10 ) {
			// Too small, round to zero
			if ( sign ) {
				result.bits = UINT16_NEGATIVE_ZERO;
			} else {
				result.bits = UINT16_POSITIVE_ZERO;
			}
			return result;
		}

		// Calculate the amount of right shift needed to denormalize the mantissa for subnormal representation:
		shift = 1 - f16Exponent;

		// Create an 11-bit mantissa by adding the implicit leading 1 bit and extracting the top 10 bits from mantissa:
		f32Mantissa |= FLOAT32_IMPLICIT_BIT;
		f16Mantissa = f32Mantissa >> ( 13 + shift );

		// Round to nearest, ties to even
		round_bit = ( f32Mantissa >> ( 12 + shift ) ) & 1;
		sticky_bits = f32Mantissa & ( ( 1u << ( 12 + shift ) ) - 1 );

		if ( round_bit && ( sticky_bits || ( f16Mantissa & 1 ) ) ) {
			f16Mantissa += 1;
		}

		result.bits = (uint16_t)(sign | f16Mantissa);
		return result;
	}

	// Extract the top 10 bits of the mantissa from 23 bits:
	f16Mantissa = f32Mantissa >> 13;

	// Extract the round bit (the first bit that will be truncated):
	round_bit = ( f32Mantissa >> 12 ) & 1;

	// Check sticky bits (all bits below bit 12):
	sticky_bits = f32Mantissa & FLOAT32_STICKY_MASK;

	if ( round_bit && ( sticky_bits || ( f16Mantissa & 1 ) ) ) {
		f16Mantissa += 1;

		// Check for mantissa overflow (carries into exponent)...
		if ( f16Mantissa > MAX_MANTISSA ) {
			f16Exponent += 1;
			f16Mantissa = 0;

			// Check for exponent overflow...
			if ( f16Exponent >= 31 ) {
				if ( sign ) {
					result.bits = UINT16_NINF; // -Infinity
				} else {
					result.bits = UINT16_PINF; // +Infinity
				}
				return result;
			}
		}
	}

	// Combine sign (1 bit), exponent (5 bits), and mantissa (10 bits):
	result.bits = (uint16_t)(sign | (f16Exponent << 10) | f16Mantissa);
	return result;
}

/**
* Converts a double-precision floating-point number to a half-precision floating-point number.
*
* @param value    double-precision floating-point number
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_float64( 5.0 );
*/
stdlib_float16_t stdlib_float16_from_float64( const double value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts a half-precision floating-point number to a single-precision floating-point number.
*
* @param value    half-precision floating-point number
* @return         single-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_float32( 2.5f );
* float y = stdlib_float16_to_float32( x );
*/
float stdlib_float16_to_float32( const stdlib_float16_t value ) {
	uint32_t f32Exponent;
	uint32_t f16Mantissa;
	uint32_t f16Exponent;
	uint32_t sign;
	uint32_t f32;
	uint16_t f16;
	float result;

	f16 = value.bits;

	// Extract sign bit and shift left 16 bits:
	sign = ((uint32_t)(f16 & STDLIB_CONSTANT_FLOAT16_SIGN_MASK)) << 16;

	// Extract exponent bits:
	f16Exponent = (f16 & STDLIB_CONSTANT_FLOAT16_EXPONENT_MASK) >> STDLIB_CONSTANT_FLOAT16_NUM_SIGNIFICAND_BITS;

	// Extract mantissa bits:
	f16Mantissa = f16 & STDLIB_CONSTANT_FLOAT16_SIGNIFICAND_MASK;

	// Handle special cases...
	if ( f16Exponent == 0 ) {
		if ( f16Mantissa == 0 ) {
			// Zero
			f32 = sign;
			memcpy( &result, &f32, sizeof(float) );
			return result;
		}

		// Denormalized number - convert to normalized float32
		f32Exponent = 1;
		while ( ( f16Mantissa & 0x0400 ) == 0 ) {
			f16Mantissa <<= 1;
			f32Exponent -= 1;
		}

		f16Mantissa &= STDLIB_CONSTANT_FLOAT16_SIGNIFICAND_MASK;
		f32Exponent = 127 - 15 + f32Exponent;
		f32 = sign | (f32Exponent << 23) | (f16Mantissa << 13);
		memcpy( &result, &f32, sizeof(float) );
		return result;
	}

	if (f16Exponent == FLOAT16_MAX_EXPONENT) {
		// Infinity or NaN
		f32 = sign | STDLIB_CONSTANT_FLOAT32_EXPONENT_MASK | (f16Mantissa << 13);
		memcpy( &result, &f32, sizeof(float) );
		return result;
	}

	// Normal case: convert exponent from float16 bias (15) to float32 bias (127)
	f32Exponent = f16Exponent - 15 + 127;
	f32 = sign | (f32Exponent << 23) | (f16Mantissa << 13);
	memcpy( &result, &f32, sizeof(float) );
	return result;
}

/**
* Converts a half-precision floating-point number to a double-precision floating-point number.
*
* @param value    half-precision floating-point number
* @return         double-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_float64( 2.5 );
* double y = stdlib_float16_to_float64( x );
*/
double stdlib_float16_to_float64( const stdlib_float16_t value ) {
	return (double)stdlib_float16_to_float32( value );
}

/**
* Converts a signed 8-bit integer to half-precision floating-point number.
*
* @param value    signed 8-bit integer
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_int8( 42 );
*/
stdlib_float16_t stdlib_float16_from_int8( const int8_t value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts an unsigned 8-bit integer to half-precision floating-point number.
*
* @param value    unsigned 8-bit integer
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_uint8( 200 );
*/
stdlib_float16_t stdlib_float16_from_uint8( const uint8_t value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts a signed 16-bit integer to half-precision floating-point number.
*
* @param value    signed 16-bit integer
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_int16( 1000 );
*/
stdlib_float16_t stdlib_float16_from_int16( const int16_t value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts an unsigned 16-bit integer to half-precision floating-point number.
*
* @param value    unsigned 16-bit integer
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_uint16( 50000 );
*/
stdlib_float16_t stdlib_float16_from_uint16( const uint16_t value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts a signed 32-bit integer to half-precision floating-point number.
*
* @param value    signed 32-bit integer
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_int32( 100000 );
*/
stdlib_float16_t stdlib_float16_from_int32( const int32_t value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts an unsigned 32-bit integer to half-precision floating-point number.
*
* @param value    unsigned 32-bit integer
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_uint32( 100000U );
*/
stdlib_float16_t stdlib_float16_from_uint32( const uint32_t value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts a signed 64-bit integer to half-precision floating-point number.
*
* @param value    signed 64-bit integer
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_int64( 1000000LL );
*/
stdlib_float16_t stdlib_float16_from_int64( const int64_t value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts an unsigned 64-bit integer to half-precision floating-point number.
*
* @param value    unsigned 64-bit integer
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_uint64( 1000000ULL );
*/
stdlib_float16_t stdlib_float16_from_uint64( const uint64_t value ) {
	return stdlib_float16_from_float32( (float)value );
}

/**
* Converts a half-precision floating-point number to a signed 32-bit integer.
*
* @param value    half-precision floating-point number
* @return         signed 32-bit integer (truncated toward zero)
*
* @example
* stdlib_float16_t x = stdlib_float16_from_float32( 2.9f );
* int32_t y = stdlib_float16_to_int32( x );
*/
int32_t stdlib_float16_to_int32( const stdlib_float16_t value ) {
	return (int32_t)stdlib_float16_to_float32( value );
}

/**
* Converts a half-precision floating-point number to an unsigned 32-bit integer.
*
* @param value    half-precision floating-point number
* @return         unsigned 32-bit integer (truncated toward zero)
*
* @example
* stdlib_float16_t x = stdlib_float16_from_float32( 2.9f );
* uint32_t y = stdlib_float16_to_uint32( x );
*/
uint32_t stdlib_float16_to_uint32( const stdlib_float16_t value ) {
	float f = stdlib_float16_to_float32( value );
	if (f < 0.0f) {
		return 0;
	}
	return (uint32_t)f;
}

/**
* Creates a half-precision floating-point number from raw bits.
*
* @param bits     raw IEEE 754 binary16 bit pattern
* @return         half-precision floating-point number
*
* @example
* stdlib_float16_t x = stdlib_float16_from_bits( 0x4000 );
* float y = stdlib_float16_to_float32( x );
* // returns 2.0f
*/
stdlib_float16_t stdlib_float16_from_bits( const uint16_t bits ) {
	stdlib_float16_t result;
	result.bits = bits;
	return result;
}

/**
* Extracts the raw bit representation from a half-precision floating-point number.
*
* @param value    half-precision floating-point number
* @return         raw IEEE 754 binary16 bit pattern
*
* @example
* stdlib_float16_t x = stdlib_float16_from_float32( 2.0f );
* uint16_t bits = stdlib_float16_to_bits( x );
* // returns 0x4000
*/
uint16_t stdlib_float16_to_bits( const stdlib_float16_t value ) {
	return value.bits;
}
